Here is the root cause:
The function calipso_skbuff_setattr() calls skb_cow() with headroom = skb_headroom(skb) + len_delta, where len_delta can be negative when the header shrinks. This integer addition can overflow, producing a large positive headroom that passes the __skb_cow() check, but the computed delta becomes negative, causing pskb_expand_head() to receive a negative nhead and trigger a BUG_ON.

Here is the patch:
  */
 static int calipso_skbuff_setattr(struct sk_buff *skb,
 				  const struct calipso_doi *doi_def,
 				  const struct netlbl_lsm_secattr *secattr)
 {
 	int ret_val;
 	struct ipv6hdr *ip6_hdr;
 	struct ipv6_opt_hdr *hop;
 	unsigned char buf[CALIPSO_MAX_BUFFER];
 	int len_delta, new_end, pad, payload;
 	unsigned int start, end;

 	ip6_hdr = ipv6_hdr(skb);
 	if (ip6_hdr->nexthdr == NEXTHDR_HOP) {
 		hop = (struct ipv6_opt_hdr *)(ip6_hdr + 1);
 		ret_val = calipso_opt_find(hop, &start, &end);
 		if (ret_val && ret_val != -ENOENT)
 			return ret_val;
 	} else {
 		start = 0;
 		end = 0;
 	}

 	memset(buf, 0, sizeof(buf));
 	ret_val = calipso_genopt(buf, start & 3, sizeof(buf), doi_def, secattr);
 	if (ret_val < 0)
 		return ret_val;

 	new_end = start + ret_val;
 	/* At this point new_end aligns to 4n, so (new_end & 4) pads to 8n */
 	pad = ((new_end & 4) + (end & 7)) & 7;
 	len_delta = new_end - (int)end + pad;
-	ret_val = skb_cow(skb, skb_headroom(skb) + len_delta);
+	ret_val = skb_cow(skb,
+			  skb_headroom(skb) + (len_delta > 0 ? len_delta : 0));
 	if (ret_val < 0)
 		return ret_val;

 	ip6_hdr = ipv6_hdr(skb); /* Reset as skb_cow() may have moved it */

 	if (len_delta) {
 		if (len_delta > 0)
 			skb_push(skb, len_delta);
 		else
 			skb_pull(skb, -len_delta);
 		memmove((char *)ip6_hdr - len_delta, ip6_hdr,
 			sizeof(*ip6_hdr) + start);
 		skb_reset_network_header(skb);
 		ip6_hdr = ipv6_hdr(skb);
 		payload = ntohs(ip6_hdr->payload_len);
 		ip6_hdr->payload_len = htons(payload + len_delta);
 	}

 	hop = (struct ipv6_opt_hdr *)(ip6_hdr + 1);
 	if (start == 0) {
 		struct ipv6_opt_hdr *new_hop = (struct ipv6_opt_hdr *)buf;

 		new_hop->nexthdr = ip6_hdr->nexthdr;
 		new_hop->hdrlen = len_delta / 8 - 1;
 		ip6_hdr->nexthdr = NEXTHDR_HOP;
 	} else {
 		hop->hdrlen += len_delta / 8;
 	}
 	memcpy((char *)hop + start, buf + (start & 3), new_end - start);
 	calipso_pad_write((unsigned char *)hop, new_end, pad);

 	return 0;
 }



